def _gen_group(target_sum, count=4, lo=33, hi=126):
    """Generate `count` values in [lo, hi] that sum to target_sum."""
    while True:
        vals = [random.randint(lo, hi) for _ in range(count - 1)]
        last = target_sum - sum(vals)
        if lo <= last <= hi:
            result = vals + [last]
            random.shuffle(result)
            return result


