def verify(name: str, serial: str) -> bool:
    """
    Validates a name/serial pair according to the crackme algorithm.

    Requirements:
      - len(name) > len(serial)  (name must be strictly longer than password)
      - len(name) >= 4
      - len(serial) >= 3
      - Both must be in charset 0-9a-zA-Z
    """
