    large = large * 2 + 10
    if large != 50:
        large -= 7
    if 'A' <= name[0] <= 'Z':
        large += 2
    if 'A' <= name[-1] <= 'Z':
        large += 3
    return large


def get_capitals(name: str) -> str:
    """Extract only uppercase letters A-P from name (step 8: uppercase A-P)."""
    # ASSUMPTION: The source says 'A~P' range for capitals extracted into C,
