def _rol32(x: int, n: int) -> int:
    """32-bit rotate left."""
    n = n % 32
    if n == 0:
        return x & 0xFFFFFFFF
    return ((x << n) | (x >> (32 - n))) & 0xFFFFFFFF

def _ror32(x: int, n: int) -> int:
    """32-bit rotate right."""
    n = n % 32
    if n == 0:
        return x & 0xFFFFFFFF
    return ((x >> n) | (x << (32 - n))) & 0xFFFFFFFF

