try:
    _VALID_PREFIXES = _find_valid_prefixes()
except Exception:
    _VALID_PREFIXES = []

def _encode_char(ch):
    """Encode a single character (already upper-case) using lookup tables."""
    if '0' <= ch <= '9':
        return _LOOKUP_NUMBER[ord(ch) - ord('0')]
