def to32(x):
    return x & 0xFFFFFFFF

def to48(x):
    return x & 0xFFFFFFFFFFFF

def javaHash(s):
    h = 0
    for x in map(ord, s):
        h = h * 31 + x
    return to32(h)

class JavaRand:
    def __init__(self, seed):
        # Java Random uses signed 32-bit seed logic
        if seed >= (1 << 31):
            seed -= (1 << 32)
        self.seed = to48(seed ^ 0x5DEECE66D)

    def next(self, bits):
        self.seed = to48(self.seed * 0x5DEECE66D + 0xB)
        return to32(self.seed >> (48 - bits))

    def nextInt(self, n):
        # Power-of-two shortcut
        if (n & -n) == n:
            return to32((n * self.next(31)) >> 31)
        bits = self.next(31)
        val = bits % n
        while bits - val + (n - 1) < 0:
            bits = self.next(31)
            val = bits % n
        return val

