    part3 = str(nlen + nnlen + alen)

    # age second character (0-based index 1), only if age has >= 2 chars
    age_part = age[1:2]  # empty string if age is only 1 char long

    part4 = age_part + str(nlen)

    serial = part1 + "-" + part2 + part3 + "-" + part4
    return serial


