    if s3 == 0:
        return False
    val_n = _val_name(name)
    expected_serial2 = (val_n * 100.0 + 15.0 * s3 - 18.0) / s3
    # Allow small floating-point tolerance
    return abs(serial2_in - expected_serial2) < 1e-4


