    if len(name) < 4:
        raise ValueError('Name must be at least 4 characters long')
    processed = _preprocess_name(name)
    if len(processed) < 4:
        raise ValueError('Name (after space processing) must be at least 4 characters long')
    return _generate_serial(processed)



