HARDCODED = "CrackMe1"

def keygen(name: str) -> str:
    """
    For each character in name:
      1. XOR it with the corresponding character of 'CrackMe1' (cycling).
      2. If the result is 0x00 (null), stop (the byte terminates the serial).
      3. Otherwise, append '0' followed by the hex digit of (xored_byte & 0x0F).
    """
    key = HARDCODED
    key_len = len(key)
    serial_chars = []
    for i, ch in enumerate(name):
        xored = ord(ch) ^ ord(key[i % key_len])
        if xored == 0:
            # null byte terminates the serial generation
            break
        low_nibble = xored & 0x0F
        # high nibble is always '0'
        high_char = '0'
        # low nibble: 0-9 -> '0'-'9', 10-15 -> 'A'-'F'
        low_char = chr(low_nibble + 0x30) if low_nibble < 10 else chr(low_nibble + 0x37)
        serial_chars.append(high_char)
        serial_chars.append(low_char)
    return ''.join(serial_chars)


def verify(name: str, serial: str) -> bool:
    """
    Generate the expected serial for 'name' and compare with the provided serial.
    The comparison is case-insensitive on the hex letters.
    """
    if len(name) <= 4:
        return False
    expected = keygen(name)
    if not expected:  # empty serial (e.g. first char XORs to zero)
        return False
    return expected.upper() == serial.upper()



