    parts = []
    for i, ch in enumerate(password):
        xored = (ord(ch) ^ XOR_KEYS[i]) & 0xFF
        # %X formats as uppercase hex, no leading zeros, minimum 1 digit
        parts.append(format(xored, 'X'))
    return ''.join(parts)


