# Helper: sum of ASCII values of a string
def char_sum(s):
    return sum(ord(c) for c in s)

# Helper: convert integer to modified string
# Each digit char: subtract 48 (ASCII '0'), add 65 (ASCII 'A')
def modified_string(n):
    digits = str(n)
    result = []
    for ch in digits:
        val = ord(ch) - 48 + 65
        result.append(chr(val))
    return ''.join(result)

