            fsName = ctypes.create_unicode_buffer(261)
            serial = ctypes.c_uint32(0)
            maxComponentLen = ctypes.c_uint32(0)
            fsFlags = ctypes.c_uint32(0)
            result = ctypes.windll.kernel32.GetVolumeInformationW(
