    xor_str = compute_xor_string(name)
    # ASSUMPTION: MD5 is applied to the XOR decimal string (UTF-8 encoded)
    expected = hashlib.md5(xor_str.encode('latin-1')).hexdigest()
    return serial.strip().lower() == expected.lower()

