def getmd5(s: str) -> str:
    """Returns lowercase hex MD5 digest of the UTF-8 encoded string."""
    return hashlib.md5(s.encode('utf-8')).hexdigest()


def keygen(name: str, double_click_time: int = 500) -> str:
    """
