def factorize(n):
    """Trial division to find prime factors of n."""
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def rsa_private_key(e, n):
    factors = factorize(n)
    if len(factors) != 2:
        raise ValueError(f'n has {len(factors)} prime factors, expected 2')
    p, q = factors[0], factors[1]
    phi_n = (p - 1) * (q - 1)
    d = modinv(e, phi_n)
    return d

def rsa_decrypt(c, d, n):
    return pow(c, d, n)

