def compute_serial(machine_guid: str, d: date) -> str:
    """Full pipeline: MachineGuid + date -> serial string."""
    s0 = machine_guid.encode("ascii")
    s1 = f1c0(s0)
    s2 = f00edc0(s1)
    s3 = f00f990(s2)
    s4 = f00eb00(s3, d)
    s5 = f00f530(s4)
    return format_password(s5)


