def _doit(num, ind, result):
    """Recursive function mirroring the C++ doit().
    Appends chosen array elements to `result` list (in the order they are printed,
    which is post-recursion, i.e. reversed from selection order).
    Returns True if a valid decomposition was found."""
    if num == 0:
        return True
    if num < 0 or ind >= ARRSIZE:
        return False

    sub = arr[ind]
    num -= sub
    ind += 1  # pre-increment: we start trying from ind+1 onward

    while not _doit(num, ind, result):
        ind += 1
        if ind >= ARRSIZE:
            return False

    # printf("%d", sub) happens here (after successful recursive call)
    result.append(sub)
    return True


def compute_second_part(num):
    """Compute the second part of the serial for the given integer num."""
    result = []
    if _doit(num, 0, result):
        return ''.join(str(x) for x in result)
    return None


