def verify(name: str, serial: str) -> bool:
    """
    The crackme validates by:
    1. Name must be at least 4 characters long.
    2. Name must be at most 32 characters long.
    3. Sort the name characters in ascending (alphabetical) ASCII order.
    4. Compare the sorted name to the provided serial.
    """
    if len(name) < 4:
        return False
    if len(name) > 32:
        return False
    expected_serial = ''.join(sorted(name))
    return serial == expected_serial


