def transform(word):
    """
    Applies the transformation described in all solutions:
    For each index i in range(len(word)):
        new_pos = ord(word[i]) % len(word)
        word[new_pos] = word[i]
    Returns the transformed string.
    """
    # Work with a mutable list of characters
    chars = list(word)
    n = len(chars)
    if n == 0:
        return word
    for i in range(n):
        ch = chars[i]
        dest = ord(ch) % n
        chars[dest] = ch
    return ''.join(chars)


def verify(name: str, serial: str) -> bool:
    """
    The program reads 'name' (Input word) and 'serial' (Guess result).
    It transforms 'name' in-place using the loop, then compares with 'serial'.
    Returns True if serial == transform(name).
    """
    return serial == transform(name)


def keygen(name: str) -> str:
    """
    Generates the correct 'Guess result' for a given input word.
    Simply apply the same transformation the binary applies.
    """
    return transform(name)



